    int sumEvenGrandparent(TreeNode* root) {

        int sum = 0;

        queue<TreeNode*> q1;
        queue<TreeNode*> q2;

        q1.push(root);

        if(root -> val % 2 == 0){

            if(root -> left)
                q2.push(root -> left);

            if(root -> right)
                q2.push(root -> right);

        }

        while(!q1.empty()){

            int n = q1.size();

            while(n--){

                TreeNode* temp = q1.front();
                q1.pop();

                if(temp -> left){

                    if(temp -> left -> val % 2 == 0){

                        if(temp -> left -> left)
                            q2.push(temp -> left -> left);

                        if(temp -> left -> right)
