                if(temp -> right){

                    if(temp -> right -> val % 2 == 0){

                        if(temp -> right -> left)
                            q2.push(temp -> right -> left);

                        if(temp -> right -> right)
                            q2.push(temp -> right -> right);

                    }

                    q1.push(temp -> right);

                }

            }

        }

        while(!q2.empty()){

            if(q2.front() -> left)
